style.css:
@-moz-document domain("roblox.com") {
/* STEAMER ROBLOX — Steam Gaming Edition */

:root {
  --steam-bg: #0b1522;
  --steam-panel: #142538;
  --steam-card: #1b3045;
  --steam-blue: #1a9fff;
  --steam-glow: #00baff;
  --steam-text: #e6f1ff;
  --steam-muted: #91a8bd;
}

/* Main background */
html,
body {
  background: var(--steam-bg) !important;
  color: var(--steam-text) !important;
}

/* Header */
header,
nav {
  background: #101e2d !important;
  border-bottom: 1px solid #234766 !important;
  box-shadow: 0 3px 18px #0008 !important;
}

/* Main panels */
main,
section,
article {
  color: var(--steam-text) !important;
}

/* Links */
a {
  color: var(--steam-light-blue, #66c0f4) !important;
  transition: color .2s ease !important;
}

a:hover {
  color: white !important;
  text-shadow: 0 0 8px var(--steam-blue) !important;
}

/* Search and text fields */
input,
textarea {
  background: #091522 !important;
  color: white !important;
  border: 1px solid #31516d !important;
  border-radius: 10px !important;
}

input:focus,
textarea:focus {
  border-color: var(--steam-blue) !important;
  box-shadow: 0 0 12px #1a9fff66 !important;
}

/* Steam blue buttons */
button {
  background: linear-gradient(
    135deg,
    #1265a0,
    #168fe0
  ) !important;
  color: white !important;
  border: 1px solid #258bd0 !important;
  border-radius: 9px !important;
  transition: .2s ease !important;
}

button:hover {
  background: linear-gradient(
    135deg,
    #168fe0,
    #25b4ff
  ) !important;
  box-shadow: 0 0 14px #1a9fff66 !important;
}

/* Rounded game images */
img {
  border-radius: 10px !important;
}

/* Roblox gaming cards */
article,
section {
  border-color: #25435d !important;
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 9px !important;
}

::-webkit-scrollbar-track {
  background: #0b1522 !important;
}

::-webkit-scrollbar-thumb {
  background: #245477 !important;
  border-radius: 10px !important;
}
}
